    walk(coll);
  }

  var scanItems = items;

  // ---------- harvest ----------
  var byCode = {};
  var uncoded = [];
  var skippedAll = [];
  var codedSources = 0;
  var sourceList = [];
  var allEx = [];
  var untaggedAll = [];
  for (var n = 0; n < scanItems.length; n++) {
    var res = await harvest(scanItems[n]);
    sourceList.push(res.source);
    res.untagged.forEach(function (u) { untaggedAll.push(u); });
    res.extracts.forEach(function (e0) { allEx.push(e0); });
    for (var s = 0; s < res.skipped.length; s++) skippedAll.push(res.skipped[s]);
    if (!res.extracts.length) {
      uncoded.push(res.source);
      continue;
    }
    codedSources += 1;
    for (var x = 0; x < res.extracts.length; x++) {
      var ex = res.extracts[x];
      for (var y = 0; y < ex.codes.length; y++) {
        var c = ex.codes[y];
        if (!byCode[c]) byCode[c] = [];
        byCode[c].push(ex);
      }
    }
  }

  // ---------- render ----------
  var ci = function (a, b) { return a.toLowerCase().localeCompare(b.toLowerCase()); };
  var codes = Object.keys(byCode).sort(ci);
  var countSources = function (list) {
    var s = new Set(list.map(function (e) { return e.source.link; }));
    return s.size;
  };
  var cell = function (text) { return String(text).replace(/\|/g, "\\|"); };
  var shorten = function (text, max) {
    text = String(text || "");
    return text.length > max ? text.slice(0, max - 1).trim() + "\u2026" : text;
  };
  var cite = function (e) {
    var line = "> **Source:** " + mdEscape(e.source.cite);
    if (e.page) line += " (p. " + e.page + ")";
    return line + " [\\[Open highlight\\]](" + e.link + ")";
  };
  var scannedLabel = (wholeLibrary ? "the entire library" : "the collection " + mdEscape(scopeName)) + " (" + scanItems.length + " source(s))";
  var out = [];
  out.push("<span style=\"color: #e03131\"><em><strong>Everything from here down to the line at the bottom is regenerated every time you refresh this note.</strong> Do not type inside it. Write any notes of your own below that line, or a refresh will erase them.</em></span>");
  out.push("");
  out.push("## Scope");
  out.push("");
  out.push("- **" + "Found " + untaggedAll.length + " highlight(s) with no code, out of " + (allEx.length + untaggedAll.length) + " highlight(s) in " + scanItems.length + " sources scanned." + "**");
  out.push("- **Scanned:** " + scannedLabel);
  out.push("- **Generated:** " + new Date().toLocaleString());
  out.push("");
  out.push("## Uncoded highlights");
  if (!untaggedAll.length) {
    out.push("");
    out.push("*Every highlight in what was scanned has at least one code.*");
  }
  untaggedAll.forEach(function (e) {
    out.push("");
    out.push(e.text ? "> " + e.text : "> *(no highlighted text, memo only)*");
    out.push("> ");
    out.push(cite(e));
    if (e.memo) {
      out.push("> ");
      out.push("> **Memo:** " + e.memo);
    }
  });
  return out.join("\n");
}}$
